<?php
namespace App\Services;
use App\Models\{Booking,BookingStatusHistory,MeetingRoom,Setting,User}; use Illuminate\Support\Facades\DB; use Illuminate\Validation\ValidationException;
class BookingService { public function create(array $data, User $user): Booking { return DB::transaction(function() use($data,$user) { $room=MeetingRoom::where('is_active',true)->lockForUpdate()->findOrFail($data['meeting_room_id']); $this->validate($room,$data); $booking=Booking::create([...$data,'user_id'=>$user->id,'booking_code'=>'BK-'.now()->format('Ymd').'-'.str_pad((string)(Booking::max('id')+1),5,'0',STR_PAD_LEFT),'status'=>'pending']); $this->history($booking,$user,'pending','Permintaan dibuat'); return $booking; }); }
 public function approve(Booking $booking, User $admin):void { DB::transaction(function() use($booking,$admin) { $booking=Booking::lockForUpdate()->findOrFail($booking->id); if($booking->status!=='pending') throw ValidationException::withMessages(['status'=>'Booking ini sudah diproses.']); $this->validate($booking->room,$booking->only('start_at','end_at','participant_count'),$booking->id); $booking->update(['status'=>'approved','approved_by'=>$admin->id,'approved_at'=>now()]); $this->history($booking,$admin,'approved','Disetujui'); }); }
 public function reject(Booking $booking, User $admin,string $reason):void { DB::transaction(function()use($booking,$admin,$reason){$booking->update(['status'=>'rejected','rejection_reason'=>$reason]);$this->history($booking,$admin,'rejected',$reason);}); }
 public function updateByAdmin(Booking $booking, array $data, User $admin): Booking { return DB::transaction(function() use($booking,$data,$admin) { $booking=Booking::lockForUpdate()->findOrFail($booking->id); if(!in_array($booking->status,['pending','approved'],true)) throw ValidationException::withMessages(['status'=>'Booking berstatus '.ucfirst($booking->status).' hanya dapat dilihat, tidak dapat diubah.']); $decision=$data['decision']??null; $reason=$data['rejection_reason']??null; unset($data['decision'],$data['rejection_reason']); if($decision && $booking->status!=='pending') throw ValidationException::withMessages(['decision'=>'Keputusan baru hanya dapat diberikan untuk booking Pending.']); $room=MeetingRoom::where('is_active',true)->lockForUpdate()->findOrFail($data['meeting_room_id']); $this->validate($room,$data,$booking->id); $booking->update($data); if($decision==='approve') { $booking->update(['status'=>'approved','approved_by'=>$admin->id,'approved_at'=>now(),'rejection_reason'=>null]); $this->history($booking,$admin,'approved','Disetujui melalui halaman edit.'); } elseif($decision==='reject') { $booking->update(['status'=>'rejected','rejection_reason'=>$reason]); $this->history($booking,$admin,'rejected',$reason); } else { $this->history($booking,$admin,$booking->status,'Data booking diperbarui oleh administrator.'); } return $booking; }); }
 public function cancel(Booking $booking,User $user):void { if($booking->status==='cancelled') return; $booking->update(['status'=>'cancelled','cancelled_at'=>now()]); $this->history($booking,$user,'cancelled','Dibatalkan'); }
 private function validate(MeetingRoom $room,array $data,?int $except=null):void { if(!$room->is_active) throw ValidationException::withMessages(['meeting_room_id'=>'Ruangan tidak aktif.']); if($data['participant_count']>$room->capacity) throw ValidationException::withMessages(['participant_count'=>'Jumlah peserta melebihi kapasitas ruangan.']); $start=\Carbon\Carbon::parse($data['start_at']);$end=\Carbon\Carbon::parse($data['end_at']); $min=(int)(Setting::where('key','min_booking_minutes')->value('value')??30);$max=(int)(Setting::where('key','max_booking_minutes')->value('value')??480); if($start->diffInMinutes($end)<$min||$start->diffInMinutes($end)>$max)throw ValidationException::withMessages(['end_at'=>"Durasi harus $min-$max menit."]); if($room->opens_at && ($start->format('H:i:s')<$room->opens_at || $end->format('H:i:s')>$room->closes_at))throw ValidationException::withMessages(['start_at'=>'Di luar jam operasional ruangan.']); $conflict=Booking::where('meeting_room_id',$room->id)->whereIn('status',Booking::BLOCKING)->when($except,fn($q)=>$q->whereKeyNot($except))->where('start_at','<',$end)->where('end_at','>',$start)->exists();if($conflict)throw ValidationException::withMessages(['start_at'=>'Jadwal bertabrakan dengan booking aktif.']); }
 private function history(Booking $b,User $u,string $s,string $n):void{BookingStatusHistory::create(['booking_id'=>$b->id,'actor_id'=>$u->id,'status'=>$s,'note'=>$n]);} }
